def type_in_chat(text: str):
    keyboard.type("t")
    sleep(0.1)
    keyboard.type(text)
    sleep(0.1)
    keyboard.press(Key.enter)
    sleep(0.5)

def create_region(coord):
    # Format coordinate as string: x,y,z
    coord_str = f"{coord[0]},{coord[1]},{coord[2]}"
    
    type_in_chat(f"//pos {coord_str} {coord_str}") #EXAMPLE //pos -9210,96,9742 -9210,96,9742
    type_in_chat(f"/rg define harhaflowerpot{coord_str} Crowenza RYgamer1") #EXAMPLE /rg define harhaflowerpot-9210,96,9742 Crowenza RYgamer1
    type_in_chat(f"/rg flag harhaflowerpot{coord_str} interact deny") #EXAMPLE /rg flag harhaflowerpot-9210,96,9742 interact allow
    type_in_chat(f"/rg setpriority -w \"Theta_the_end\" harhaflowerpot{coord_str} 5") #EXAMPLE /rg setpriority -w "Theta" harhaflowerpot-9210,96,9742 1

for coord in listOfCoordinates:
    create_region(coord)

